async function pullAndMerge(){const remote=await cloud.pull();const remoteState=remote.state||c.defaults(),remoteRevision=Number(remote.revision||0);c.validateState(remoteState);const result=sync.merge(base||c.defaults(),state,remoteState);revision=remoteRevision;base=sync.clone(remoteState);if(result.conflicts.length){conflictContext=result;status('Senkronizasyon çatışması');showConflict();return;}state=result.state;localDirty=!sync.same(state,remoteState);persist();status(localDirty?'Birleştirildi · eşitle':'Bulut güncel');render();if(localDirty)setTimeout(()=>syncNow(false),750);}
async function pullInitial(){const server=await cloud.pull(),remoteState=server.state||c.defaults();c.validateState(remoteState);const remoteRev=Number(server.revision||0),record=sync.useCache(localKey());if(record?.state){const merged=sync.merge(record.baseState||record.state,record.state,remoteState);state=merged.state;revision=remoteRev;base=sync.clone(remoteState);localDirty=!sync.same(state,remoteState);if(merged.conflicts.length){conflictContext=merged;status('Çakışma bulundu');showConflict();}else if(localDirty){await syncNow(false);}else status('Bulut güncel');}else{state=sync.clone(remoteState);revision=remoteRev;base=sync.clone(remoteState);localDirty=false;status('Bulut güncel');}const reviewChanged=p.snapshotWeeks(state);if(reviewChanged){localDirty=true;setTimeout(()=>syncNow(false),850)}persist();}
async function showConflict(){if(!conflictContext)return;const count=conflictContext.conflicts.length;openModal('Cihazlar arası değişiklik çatışması',`<div class="notice">${count} kayıt iki cihazda farklı değiştirildi. Hiçbir yerel değişiklik otomatik silinmedi. Devam etmeden önce JSON yedeği almanı öneririz.</div><div class="action-row"><button class="ghost-btn" data-action="export">JSON yedeği al</button></div><p class="muted-text">Çakışan kayıtlar: ${esc(conflictContext.conflicts.slice(0,10).map(x=>x.collection+': '+x.id).join(', '))}</p><div class="modal-footer"><button class="ghost-btn" data-action="resolve-conflict" data-choice="remote">Sunucudaki sürümü seç</button><button class="primary-btn" data-action="resolve-conflict" data-choice="local">Bu cihazdaki sürümü seç</button></div>`);}
